def merge_words(words):
    i = 1
    while i < len(words):
        word1 = words[i - 1]
        word2 = words[i]
        max_overlap = 0
        for j in range(1, min(len(word1), len(word2)) + 1):
            if word1[-j:] == word2[:j]:
                max_overlap = j
        words[i] = word1 + word2[max_overlap:]
        i += 1
    return words[-1]

def main():
    n = int(input())
    words = input().split()
    compressed_word = merge_words(words)
    print(compressed_word)

if __name__ == "__main__":
    main()
